CREATE OR REPLACE FUNCTION public.enforce_workspace_tenant() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN RAISE EXCEPTION 'Tenant and workspace associations are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER facts_tenant_immutable BEFORE UPDATE ON public.business_facts FOR EACH ROW EXECUTE FUNCTION public.enforce_workspace_tenant();
CREATE TRIGGER documents_tenant_immutable BEFORE UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.enforce_workspace_tenant();
CREATE TRIGGER conversations_tenant_immutable BEFORE UPDATE ON public.conversations FOR EACH ROW EXECUTE FUNCTION public.enforce_workspace_tenant();
CREATE TRIGGER runs_tenant_immutable BEFORE UPDATE ON public.agent_runs FOR EACH ROW EXECUTE FUNCTION public.enforce_workspace_tenant();
CREATE TRIGGER approvals_tenant_immutable BEFORE UPDATE ON public.approvals FOR EACH ROW EXECUTE FUNCTION public.enforce_workspace_tenant();
CREATE OR REPLACE FUNCTION public.consume_credits(_org uuid, _amount int, _ref text) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE bal int; sub public.subscriptions%ROWTYPE; BEGIN IF NOT public.has_org_role(_org,'member') THEN RAISE EXCEPTION 'forbidden'; END IF; IF _amount <= 0 OR _amount > 1000 THEN RAISE EXCEPTION 'invalid amount'; END IF; PERFORM 1 FROM public.organizations WHERE id = _org FOR UPDATE; SELECT * INTO sub FROM public.subscriptions WHERE org_id = _org; IF sub.org_id IS NULL OR sub.status NOT IN ('active','trialing') THEN RAISE EXCEPTION 'no active subscription'; END IF; IF sub.status = 'trialing' AND (sub.trial_ends_at IS NULL OR sub.trial_ends_at <= now()) THEN RAISE EXCEPTION 'trial expired'; END IF; bal := public.credit_balance(_org); IF bal < _amount THEN RAISE EXCEPTION 'insufficient credits'; END IF; INSERT INTO public.credit_ledger(org_id,delta,reason,ref,created_by) VALUES(_org,-_amount,'usage',left(_ref,100),auth.uid()); RETURN bal - _amount; END $$;